import { memo } from "react";

const BRICK_EMOJIS: string[] = [
  "🧵", "🦐", "🍋", "🍇", "🧀",
  "🍑", "🍒", "🥝", "🍌", "🍉",
  "🍍", "🥭", "🐋", "🌵", "🍈",
  "🥥", "🐨", "🥑", "🌽", "🥕",
  "🍄", "🦓", "🥔", "🌶️", "🍸",
  "🥒", "🦑", "🥦", "🧄", "🧊",
  "🐶", "🐰", "🦊", "🐻", "🦥",
];

interface BrickCellProps {
  row: number;
  col: number;
  brick: number | null;
  frozen?: boolean;
  frozenLevel?: number;
  isSelected: boolean;
  isInGroup: boolean;
  isCandidate: boolean;
  isClearing?: boolean;
  isShaking?: boolean;
  isHint?: boolean;
  isSwapFirst?: boolean;
  isToolActive?: boolean;
  offsetX?: number;
  offsetY?: number;
  onMouseDown?: (e: React.MouseEvent) => void;
  onClick?: (e: React.MouseEvent) => void;
  onTouchStart?: (e: React.TouchEvent) => void;
}

const BrickCell = memo(function BrickCell({
  row,
  col,
  brick,
  frozen = false,
  frozenLevel = 0,
  isSelected,
  isInGroup,
  isCandidate,
  isClearing = false,
  isShaking = false,
  isHint = false,
  isSwapFirst = false,
  isToolActive = false,
  offsetX = 0,
  offsetY = 0,
  onMouseDown,
  onClick,
  onTouchStart,
}: BrickCellProps) {
  let cellClasses =
    "w-full aspect-square rounded-lg cursor-pointer flex items-center justify-center select-none touch-none overflow-hidden relative";

  if (brick === null) {
    cellClasses += " bg-slate-800/40 border border-slate-700/50 hover:bg-slate-700/40";
  } else {
    cellClasses += " brick-cell border border-amber-200";
    if (isClearing) {
      cellClasses += " brick-clearing";
    } else if (isShaking) {
      cellClasses += " brick-shaking";
    } else if (isSwapFirst) {
      cellClasses += " ring-4 ring-violet-400 ring-opacity-90 scale-110 z-10 animate-pulse";
    } else if (isSelected) {
      cellClasses += " ring-4 ring-yellow-400 ring-opacity-90 scale-110 z-10";
    } else if (isCandidate) {
      cellClasses +=
        " ring-4 ring-emerald-400 ring-opacity-90 scale-105 animate-pulse";
    } else if (isHint) {
      cellClasses +=
        " ring-4 ring-cyan-400 ring-opacity-90 scale-105 animate-pulse";
    } else if (isInGroup) {
      cellClasses += " ring-2 ring-white/70";
    } else if (isToolActive) {
      cellClasses += " hover:ring-4 hover:ring-purple-400 hover:ring-opacity-80 hover:scale-105";
    }
  }

  const emoji = brick !== null ? BRICK_EMOJIS[brick] : null;

  if (offsetX !== 0 || offsetY !== 0) {
    cellClasses += " brick-dragging";
  }

  const style: React.CSSProperties = {};
  if (offsetX !== 0 || offsetY !== 0) {
    style.transform = `translate(${offsetX}px, ${offsetY}px)`;
    style.zIndex = 20;
  }

  return (
    <div
      className={cellClasses}
      style={style}
      data-row={row}
      data-col={col}
      onMouseDown={onMouseDown}
      onClick={onClick}
      onTouchStart={onTouchStart}
    >
      {emoji && (
        <span
          className="leading-none relative z-10"
          style={{
            fontSize: "clamp(18px, 70%, 36px)",
          }}
        >
          {emoji}
        </span>
      )}
      {frozenLevel === 1 && (
        <div
          className="absolute inset-0 pointer-events-none rounded-lg"
          style={{
            background:
              "linear-gradient(135deg, rgba(125,211,252,0.45) 0%, rgba(186,230,253,0.35) 50%, rgba(125,211,252,0.45) 100%)",
            boxShadow:
              "inset 0 0 8px rgba(255,255,255,0.6), inset 0 0 2px rgba(255,255,255,0.8)",
            border: "1px solid rgba(186,230,253,0.5)",
          }}
        />
      )}
      {frozenLevel >= 2 && (
        <div
          className="absolute inset-0 pointer-events-none rounded-lg"
          style={{
            background:
              "linear-gradient(135deg, rgba(59,130,246,0.55) 0%, rgba(147,197,253,0.4) 50%, rgba(59,130,246,0.55) 100%)",
            boxShadow:
              "inset 0 0 10px rgba(255,255,255,0.7), inset 0 0 3px rgba(255,255,255,0.9)",
            border: "2px solid rgba(147,197,253,0.7)",
          }}
        />
      )}
    </div>
  );
}, (prev, next) => {
  return (
    prev.brick === next.brick &&
    prev.frozen === next.frozen &&
    prev.frozenLevel === next.frozenLevel &&
    prev.isSelected === next.isSelected &&
    prev.isInGroup === next.isInGroup &&
    prev.isCandidate === next.isCandidate &&
    prev.isClearing === next.isClearing &&
    prev.isShaking === next.isShaking &&
    prev.isHint === next.isHint &&
    prev.isSwapFirst === next.isSwapFirst &&
    prev.isToolActive === next.isToolActive &&
    prev.offsetX === next.offsetX &&
    prev.offsetY === next.offsetY
  );
});

export default BrickCell;