export async function updatePkRoom(
  roomId: string,
  updates: Partial<{
    status: string;
    hostReady: boolean;
    guestReady: boolean;
    currentQuestion: number;
    guestUuid: string | null;
    guestNickname: string | null;
    guestSourceType: "import" | "random" | null;
    guestImportRecordId: string | null;
    guestImportRecordTitle: string | null;
    guestQuestionWords: Array<{ spelling: string; meaning: string }> | null;
  }>
): Promise<PkRoom | null> {
  try {
    const data: Record<string, unknown> = { updated_at: Date.now() };
    if (updates.status !== undefined) data.status = updates.status;
    if (updates.hostReady !== undefined) data.host_ready = updates.hostReady;
    if (updates.guestReady !== undefined) data.guest_ready = updates.guestReady;
    if (updates.currentQuestion !== undefined) data.current_question = updates.currentQuestion;
    if (updates.guestUuid !== undefined) data.guest_uuid = updates.guestUuid;
    if (updates.guestNickname !== undefined) data.guest_nickname = updates.guestNickname;
    if (updates.guestSourceType !== undefined) data.guest_source_type = updates.guestSourceType;
    if (updates.guestImportRecordId !== undefined) data.guest_import_record_id = updates.guestImportRecordId;
    if (updates.guestImportRecordTitle !== undefined) data.guest_import_record_title = updates.guestImportRecordTitle;
    if (updates.guestQuestionWords !== undefined) data.guest_question_words = updates.guestQuestionWords;

    const { data: result, error } = await supabase
      .from("pk_rooms")
      .update(data)
      .eq("id", roomId.toUpperCase())
      .select()
      .limit(1);

    if (error) {
      console.error("更新房间失败:", error.message);
      return null;
    }
    if (!result || result.length === 0) return null;
    return rowToRoom(result[0]);
  } catch (e) {
    console.error("更新房间异常:", e);
    return null;
  }
}

export async function deletePkRoom(roomId: string): Promise<boolean> {
  try {
    const { error } = await supabase
      .from("pk_rooms")
      .delete()
      .eq("id", roomId.toUpperCase());

    if (error) {
      console.error("删除房间失败:", error.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("删除房间异常:", e);
    return false;
  }
}

export async function submitPkAnswer(params: {
  roomId: string;
  questionIndex: number;
  questionWord: string;
  correctAnswer: string;
  options: string[];
  isHost: boolean;
  answer: string;
  time: number;
  score: number;
}): Promise<boolean> {
  try {
    const upsertData: Record<string, unknown> = {
      room_id: params.roomId,
      question_index: params.questionIndex,
      question_word: params.questionWord,
      correct_answer: params.correctAnswer,
      options: params.options,
    };
    if (params.isHost) {
      upsertData.host_question_word = params.questionWord;
      upsertData.host_correct_answer = params.correctAnswer;
    } else {
      upsertData.guest_question_word = params.questionWord;
      upsertData.guest_correct_answer = params.correctAnswer;
    }

    const { error: upsertError } = await supabase
      .from("pk_answers")
      .upsert(upsertData, { onConflict: "room_id,question_index" });

    if (upsertError) {
      console.error("upsert答案行失败:", upsertError.message);
    }

    const updateData: Record<string, unknown> = {};
    if (params.isHost) {
      updateData.host_question_word = params.questionWord;
      updateData.host_correct_answer = params.correctAnswer;
      updateData.host_answer = params.answer;
      updateData.host_time = params.time;
      updateData.host_score = params.score;
    } else {
      updateData.guest_question_word = params.questionWord;
      updateData.guest_correct_answer = params.correctAnswer;
      updateData.guest_answer = params.answer;
      updateData.guest_time = params.time;
      updateData.guest_score = params.score;
    }

    const { error: updateError } = await supabase
      .from("pk_answers")
      .update(updateData)
      .eq("room_id", params.roomId)
      .eq("question_index", params.questionIndex);

    if (updateError) {
      console.error("更新答案失败:", updateError.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("提交答案异常:", e);
    return false;
  }
}

export async function fetchPkAnswers(roomId: string): Promise<PkAnswer[]> {
  try {
    const { data, error } = await supabase
      .from("pk_answers")
      .select("*")
      .eq("room_id", roomId)
      .order("question_index", { ascending: true });

    if (error) return [];
    return (data || []).map(rowToAnswer);
  } catch (e) {
    console.error("获取答题记录异常:", e);
    return [];
  }
}

